html:
{%- set project = doc -%}
{%- set client = frappe.get_doc("ClientProfile", project.client) -%}
{%- set client_email = frappe.db.get_value("User", client.user, "email") if client.user else None -%}
{%- set generated_at = frappe.utils.now_datetime().strftime("%d/%m/%Y à %H:%M") -%}
{%- set description_text = frappe.utils.strip_html(project.description or "") -%}
{%- set deliverables_text = project.deliverables or "" -%}
{%- set exclusions_text = project.exclusions or "" -%}
{%- set deadlines_text = project.deadlines or "" -%}
{%- set category_name = frappe.db.get_value("ServiceCategory", project.category, "category_name") if project.category else None -%}
{%- set sub_category_name = frappe.db.get_value("ServiceSubCategory", project.sub_category, "subcategory_name") if project.sub_category else None -%}
{%- set client_logo = client.logo or "" -%}
{%- if client_logo and not client_logo.startswith("data:") and not client_logo.startswith("http") -%}
	{%- set client_logo = frappe.utils.get_url(client_logo) -%}
{%- endif -%}
{%- set client_initial = (client.company_name or "E")[0]|upper -%}
{%- set author_name = ((client.first_name or "") ~ " " ~ (client.last_name or "")).strip() -%}
{%- set expected_end_display = frappe.utils.formatdate(project.expected_end_date) if project.expected_end_date else None -%}
{%- set budget_display = ("%d"|format(project.budget_min) if project.budget_min else "?") ~ " € — " ~ ("%d"|format(project.budget_max) if project.budget_max else "?") ~ " €" if (project.budget_min or project.budget_max) else "À définir" -%}
{%- set delay_display = (project.delivery_delay_days|string ~ " jours") if project.delivery_delay_days else None -%}
{%- set has_project_details = project.need_type or project.channel or category_name or sub_category_name or delay_display or expected_end_display or project.urgency or project.estimated_duration -%}
<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<title>Cahier des Charges — {{ project.title }}</title>
<style>
	body { font-family: Arial, Helvetica, sans-serif; color: #111111; font-size: 11.5px; margin: 0; padding: 18px; background: #ffffff; }
	.doc { max-width: 720px; margin: 0 auto; }

	table { border-collapse: collapse; width: 100%; }
	.header-table { border: 1.4px solid #000000; margin-bottom: 0; }
	.header-table td { border-left: 1px solid #000000; padding: 8px 12px; vertical-align: middle; }
	.header-table td:first-child { border-left: none; }

	.logo-cell { width: 86px; text-align: center; }
	.logo-img { max-width: 68px; max-height: 68px; object-fit: contain; display: block; margin: 0 auto; }
	.logo-fallback { width: 58px; height: 58px; border: 1px solid #000000; border-radius: 6px; display: flex;
		align-items: center; justify-content: center; font-weight: bold; font-size: 22px; margin: 0 auto; }

	.title-cell { text-align: center; }
	.title-cell .doc-title { font-size: 16px; font-weight: bold; text-transform: uppercase; letter-spacing: 0.02em; }
	.title-cell .doc-subtitle { font-size: 12px; margin-top: 3px; color: #333333; }

	.meta-cell { width: 180px; font-size: 10px; }
	.meta-row { margin-bottom: 6px; }
	.meta-row:last-child { margin-bottom: 0; }
	.meta-row .lbl { display: block; font-weight: bold; }
	.meta-row .val { display: block; margin-top: 1px; }

	.section-bar { border: 1.4px solid #000000; border-bottom: none; background: #e3e3e3; text-align: center;
		font-weight: bold; font-size: 11.5px; text-transform: uppercase; letter-spacing: 0.03em;
		padding: 5px; margin-top: 14px; page-break-after: avoid; }

	.doc-table { border: 1.4px solid #000000; margin-bottom: 0; }
	.doc-table tr { page-break-inside: avoid; }
	.doc-table td.cell { border-top: 1px solid #000000; border-left: 1px solid #000000; padding: 6px 12px;
		vertical-align: top; width: 50%; }
	.doc-table tr:first-child td.cell { border-top: none; }
	.doc-table td.cell:first-child { border-left: none; }

	.lbl { font-weight: bold; }
	.block-text { white-space: pre-wrap; font-weight: normal; margin-top: 3px; line-height: 1.5; }

	.skills-row td { border-top: 1px solid #000000; padding: 8px 12px; }
	.skill-pill { display: inline-block; border: 1px solid #000000; border-radius: 999px; padding: 2px 10px;
		margin: 0 5px 5px 0; font-size: 10px; }
</style>
</head>
<body>
<div class="doc">

	<table class="header-table">
		<tr>
			<td class="logo-cell">
				{%- if client_logo -%}
				<img class="logo-img" src="{{ client_logo }}" alt="{{ client.company_name or 'Logo' }}">
				{%- else -%}
				<div class="logo-fallback">{{ client_initial }}</div>
				{%- endif -%}
			</td>
			<td class="title-cell">
				<div class="doc-title">Cahier des charges</div>
				<div class="doc-subtitle">{{ project.title }}</div>
			</td>
			<td class="meta-cell">
				<div class="meta-row">
					<span class="lbl">Référence</span>
					<span class="val">{{ project.name }}</span>
				</div>
				<div class="meta-row">
					<span class="lbl">Date</span>
					<span class="val">{{ generated_at }}</span>
				</div>
			</td>
		</tr>
	</table>

	<p class="section-bar">Acteurs du projet</p>
	<table class="doc-table">
		<tr><td class="cell" colspan="2"><span class="lbl">Client :</span> {{ client.company_name or "Non renseigné" }}</td></tr>
		{%- if client.sector or client.country -%}
		<tr>
			{%- if client.sector and client.country -%}
			<td class="cell"><span class="lbl">Secteur d'activité :</span> {{ client.sector }}</td>
			<td class="cell"><span class="lbl">Pays :</span> {{ client.country }}</td>
			{%- elif client.sector -%}
			<td class="cell" colspan="2"><span class="lbl">Secteur d'activité :</span> {{ client.sector }}</td>
			{%- else -%}
			<td class="cell" colspan="2"><span class="lbl">Pays :</span> {{ client.country }}</td>
			{%- endif -%}
		</tr>
		{%- endif -%}
		{%- if author_name -%}
		<tr>
			<td class="cell"><span class="lbl">Contact :</span> {{ author_name }}</td>
			<td class="cell"><span class="lbl">Fonction :</span> Client</td>
		</tr>
		{%- endif -%}
		{%- if client.phone or client_email -%}
		<tr>
			{%- if client.phone and client_email -%}
			<td class="cell"><span class="lbl">Téléphone :</span> {{ client.phone }}</td>
			<td class="cell"><span class="lbl">Email :</span> {{ client_email }}</td>
			{%- elif client.phone -%}
			<td class="cell" colspan="2"><span class="lbl">Téléphone :</span> {{ client.phone }}</td>
			{%- else -%}
			<td class="cell" colspan="2"><span class="lbl">Email :</span> {{ client_email }}</td>
			{%- endif -%}
		</tr>
		{%- endif -%}
	</table>

	<p class="section-bar">Définition du projet</p>
	<table class="doc-table">
		<tr><td class="cell" colspan="2"><span class="lbl">Titre du projet :</span> {{ project.title }}</td></tr>
		{%- if project.need_type or project.channel -%}
		<tr>
			{%- if project.need_type and project.channel -%}
			<td class="cell"><span class="lbl">Type de besoin :</span> {{ project.need_type }}</td>
			<td class="cell"><span class="lbl">Canal :</span> {{ project.channel }}</td>
			{%- elif project.need_type -%}
			<td class="cell" colspan="2"><span class="lbl">Type de besoin :</span> {{ project.need_type }}</td>
			{%- else -%}
			<td class="cell" colspan="2"><span class="lbl">Canal :</span> {{ project.channel }}</td>
			{%- endif -%}
		</tr>
		{%- endif -%}
		{%- if category_name or sub_category_name -%}
		<tr>
			{%- if category_name and sub_category_name -%}
			<td class="cell"><span class="lbl">Catégorie :</span> {{ category_name }}</td>
			<td class="cell"><span class="lbl">Sous-catégorie :</span> {{ sub_category_name }}</td>
			{%- elif category_name -%}
			<td class="cell" colspan="2"><span class="lbl">Catégorie :</span> {{ category_name }}</td>
			{%- else -%}
			<td class="cell" colspan="2"><span class="lbl">Sous-catégorie :</span> {{ sub_category_name }}</td>
			{%- endif -%}
		</tr>
		{%- endif -%}
		{%- if description_text -%}
		<tr><td class="cell" colspan="2"><span class="lbl">Objectif du projet :</span><div class="block-text">{{ description_text }}</div></td></tr>
		{%- endif -%}
		<tr>
			{%- if project.location -%}
			<td class="cell"><span class="lbl">Localisation :</span> {{ project.location }}</td>
			{%- else -%}
			<td class="cell"><span class="lbl">Localisation :</span> Non renseignée</td>
			{%- endif -%}
			<td class="cell"><span class="lbl">Budget estimé :</span> {{ budget_display }}</td>
		</tr>
		{%- if delay_display or expected_end_display -%}
		<tr>
			{%- if delay_display and expected_end_display -%}
			<td class="cell"><span class="lbl">Délai de réalisation :</span> {{ delay_display }}</td>
			<td class="cell"><span class="lbl">Date de fin prévue :</span> {{ expected_end_display }}</td>
			{%- elif delay_display -%}
			<td class="cell" colspan="2"><span class="lbl">Délai de réalisation :</span> {{ delay_display }}</td>
			{%- else -%}
			<td class="cell" colspan="2"><span class="lbl">Date de fin prévue :</span> {{ expected_end_display }}</td>
			{%- endif -%}
		</tr>
		{%- endif -%}
		{%- if project.urgency or project.estimated_duration -%}
		<tr>
			{%- if project.urgency and project.estimated_duration -%}
			<td class="cell"><span class="lbl">Urgence :</span> {{ project.urgency }}</td>
			<td class="cell"><span class="lbl">Durée estimée :</span> {{ project.estimated_duration }}</td>
			{%- elif project.urgency -%}
			<td class="cell" colspan="2"><span class="lbl">Urgence :</span> {{ project.urgency }}</td>
			{%- else -%}
			<td class="cell" colspan="2"><span class="lbl">Durée estimée :</span> {{ project.estimated_duration }}</td>
			{%- endif -%}
		</tr>
		{%- endif -%}
		<tr><td class="cell" colspan="2"><span class="lbl">Budget flexible :</span> {{ "Oui" if project.budget_flexible else "Non" }}</td></tr>
		{%- if project.skills -%}
		<tr class="skills-row"><td colspan="2">
			<span class="lbl">Compétences recherchées :</span><br>
			{%- for skill in project.skills.split(",") -%}
				{%- if skill.strip() -%}<span class="skill-pill">{{ skill.strip() }}</span>{%- endif -%}
			{%- endfor -%}
		</td></tr>
		{%- endif -%}
	</table>

	{%- if deliverables_text or exclusions_text or deadlines_text -%}
	<p class="section-bar">Périmètre du projet</p>
	<table class="doc-table">
		{%- if deliverables_text -%}
		<tr><td class="cell" colspan="2"><span class="lbl">Livrables :</span><div class="block-text">{{ deliverables_text }}</div></td></tr>
		{%- endif -%}
		{%- if exclusions_text -%}
		<tr><td class="cell" colspan="2"><span class="lbl">Exclusions :</span><div class="block-text">{{ exclusions_text }}</div></td></tr>
		{%- endif -%}
		{%- if deadlines_text -%}
		<tr><td class="cell" colspan="2"><span class="lbl">Échéances :</span><div class="block-text">{{ deadlines_text }}</div></td></tr>
		{%- endif -%}
	</table>
	{%- endif -%}

</div>
</body>
</html>
